"""Render the minutes-of-meeting as mail-ready Markdown. This is the approval
page for Stage 1: every item carries its verbatim so it can be checked."""
from collections import defaultdict


def render(meeting, ex, stored, flags, cost):
    by_id = {s["id"]: s for s in stored}
    out = [f"# MoM — {meeting['title']}",
           f"{meeting['date']} · project `{meeting['project']}` · {meeting.get('duration', '')}",
           "", "_Draft generated by CHEETAAAH. Nothing has been changed anywhere. "
           "Reply with accept / edit / reject per item._", "",
           "## Summary", ex.summary, ""]

    if flags:
        out += ["## ⚠ Reversals — needs your call"]
        for f in flags:
            n, o = f["new"], f["old"]
            out += [f"- **{n['component']}** — today: *{n['instruction']}*",
                    f"  - today ({n['date']}, {n['said_by']}): \"{n['verbatim']}\"",
                    f"  - earlier ({o['date']}, {o['said_by']}): \"{o['verbatim']}\"",
                    f"  - why: {f['why']}",
                    f"  - default: today wins. Confirm?"]
        out += [""]

    out += ["## Decisions"]
    for d, s in zip(ex.decisions, stored):
        tag = {"same": " _(restates an earlier decision)_",
               "refines": " _(refines an earlier decision)_",
               "reverses": " _(REVERSES an earlier decision — see above)_"}.get(s["relation"], "")
        out += [f"- `{s['id']}` **{d.component}** — {d.instruction}{tag}",
                f"  - \"{d.verbatim}\" — {d.said_by} · confidence {d.confidence:.0%}"]
    out += [""]

    groups = defaultdict(list)
    for a in ex.actionables:
        groups[a.owner or "unassigned"].append(a)
    out += ["## Actionables"]
    for owner in sorted(groups, key=lambda o: (o == "unassigned", o.lower())):
        out += [f"### {owner}"]
        for a in groups[owner]:
            due = f" · due {a.due}" if a.due else ""
            out += [f"- [ ] **{a.component}** ({a.type}) — {a.instruction}{due}",
                    f"  - \"{a.verbatim}\" — {a.said_by}"]
        out += [""]

    if ex.open_questions:
        out += ["## Open questions"] + [f"- {q}" for q in ex.open_questions] + [""]

    out += ["## People", ", ".join(ex.people) or "—", "",
            f"---", f"_LLM cost for this meeting: ${cost:.4f}_"]
    return "\n".join(out)
